package com.veloster.vehicle;

import android.graphics.Canvas;
import android.graphics.Paint;

/** 48x28 LED gallop animation: ten original TaxiCluster.STRIDE bitmap frames. */
final class HorseFrames {
    private HorseFrames() {}
    // Source: sung9155/i30-pd-dashboard shared/src/com/veloster/vehicle/TaxiCluster.java
    private static final String[] STRIDE = {
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        ""
    };
    static final boolean[][] FRAMES = decode();
    private static boolean[][] decode() {
        boolean[][] frames = new boolean[STRIDE.length][48*28];
        for (int k=0;k<STRIDE.length;k++) {
            if (STRIDE[k].length()!=336) throw new IllegalStateException("Bad horse frame "+k+": "+STRIDE[k].length());
            for (int i=0;i<48*28;i++) frames[k][i]=(Character.digit(STRIDE[k].charAt(i>>2),16)>>(3-(i&3))&1)!=0;
        }
        return frames;
    }
    static void draw(Canvas c, Paint p, float left, float top, float width, float height, int frame, int color) {
        boolean[] bits=FRAMES[((frame%FRAMES.length)+FRAMES.length)%FRAMES.length];
        float w=width/48f,h=height/28f;
        p.setStyle(Paint.Style.FILL);p.setColor(color);
        for(int y=0;y<28;y++)for(int x=0;x<48;x++)if(bits[y*48+x])
            c.drawRect(left+x*w,top+y*h,left+(x+.8f)*w,top+(y+.8f)*h,p);
    }
}
